const items = $input.all();
const out = [];
for (const item of items) {
  const email = item.json || {};
  const subject = (email.subject || '') + '';
  const body = (email.body || email.text || email.html || '') + '';
  const subjRe = /\[([^\]]+)\]\s*(?:PR\s+)?[Rr]un failed:\s*(.+?)\s+-\s+(.+?)\s+\(([0-9a-f]+)\)\s*$/;
  const m = subject.match(subjRe);
  if (!m) continue;
  const repo = m[1];
  if (!repo || !repo.includes('n8n-io/n8n')) continue;
  const runMatch = body.match(/\/actions\/runs\/(\d+)/);
  const runId = runMatch ? runMatch[1] : null;
  if (!runId) continue;
  const branchOrPrTitle = m[3].trim();
  const linearMatch = branchOrPrTitle.match(/\b([a-z]+-\d+)\b/i);
  const failedJobMatches = [...body.matchAll(/\*[^*]+\*\s*\/\s*([^\n]+)\nFailed in/g)];
  const failedJobNames = failedJobMatches.map((mm) => mm[1].trim());
  out.push({
    json: {
      repo,
      workflowName: m[2].trim(),
      branchOrPrTitle,
      shortSha: m[4].trim(),
      runId,
      runUrl: 'https://github.com/n8n-io/n8n/actions/runs/' + runId,
      failedJobNames,
      failedJobCount: failedJobNames.length,
      linearId: linearMatch ? linearMatch[1].toUpperCase() : null,
      subject,
    },
  });
}
return out;

const meta = $('Parse Email').first().json;
const items = $input.all();
const out = [];
for (const item of items) {
  const response = item.json || {};
  const allJobs = response.jobs || [];
  const failed = allJobs.filter((j) => j.conclusion === 'failure');
  failed.sort((a, b) => new Date(a.started_at) - new Date(b.started_at));
  const job = failed[0];
  if (!job) continue;
  const failedStep = (job.steps || []).find((s) => s.conclusion === 'failure');
  out.push({
    json: {
      ...meta,
      jobId: job.id,
      jobName: job.name,
      jobUrl: job.html_url,
      branch: job.head_branch || meta.branchOrPrTitle,
      failedStepName: failedStep ? failedStep.name : null,
    },
  });
}
return out;

const meta = $('Pick First Failed Job').first().json;
const items = $input.all();
const out = [];
for (const item of items) {
  const raw = typeof item.json.data === 'string' ? item.json.data : (item.json.body || '');
  const log = String(raw);
  const clean = log.replace(/^\S+T\S+Z\s/gm, '');
  let failFile = (clean.match(/FAIL\s+(\S+\.(?:test|spec)\.[tj]sx?)/) || [])[1];
  if (!failFile) failFile = (clean.match(/\u00d7\s+(\S+\.(?:test|spec)\.[tj]sx?)/) || [])[1];
  if (!failFile) failFile = null;
  let testNameMatch = clean.match(/\u25cf\s+(.+?)\n/);
  if (!testNameMatch) testNameMatch = clean.match(/\u2715\s+(.+?)\n/);
  if (!testNameMatch) testNameMatch = clean.match(/FAIL\s+.+\n\s*(.+?)\n/);
  const failTest = testNameMatch ? testNameMatch[1].trim() : null;
  let errSnippet = '';
  const markerIdx = clean.search(/[\u25cf\u2715]\s+/);
  if (markerIdx >= 0) {
    errSnippet = clean.substring(markerIdx, markerIdx + 4000).split('\n').slice(0, 25).join('\n').slice(0, 1800);
  } else {
    const errIdx = clean.search(/^\s*(Error|AssertionError|TypeError|##\[error\]):/m);
    if (errIdx >= 0) {
      errSnippet = clean.substring(errIdx, errIdx + 1500).split('\n').slice(0, 20).join('\n');
    }
  }
  out.push({
    json: {
      ...meta,
      failFile: failFile || 'unknown',
      failTest: failTest || (meta.failedStepName || 'unknown'),
      errSnippet: errSnippet || '(no parseable error block - open the job logs)',
    },
  });
}
return out;
